def meanfig():
    W,H=260,220
    o='<line x1="40" y1="20" x2="40" y2="190" stroke="#1c7ab8" stroke-width="1.8"/><line x1="40" y1="190" x2="230" y2="190" stroke="#1c7ab8" stroke-width="1.8"/>'
    o+=T(34,26,'y',13,'end')+T(236,194,'x',13,'start')+T(30,102,'ȳ',13,'end')+T(138,208,'x̄',13)
    o+='<line x1="40" y1="100" x2="220" y2="100" stroke="#1c7ab8" stroke-width="1.8"/><line x1="138" y1="30" x2="138" y2="190" stroke="#1c7ab8" stroke-width="1.8"/>'
    o+='<line x1="40" y1="165" x2="215" y2="38" stroke="#1c7ab8" stroke-width="2"/><polygon points="220,34 207,36 214,46" fill="#1c7ab8"/>'+T(216,60,'ŷ',14,'start')
    return svg(W,H,'Regression line ŷ rising to the right and passing through the point where the horizontal line y-bar and vertical line x-bar meet',o)
def resfig():
    W,H=300,220
    o='<line x1="30" y1="20" x2="30" y2="190" stroke="#111" stroke-width="2"/><line x1="30" y1="190" x2="270" y2="190" stroke="#111" stroke-width="2"/>'+T(24,26,'y',13,'end')
    o+='<line x1="30" y1="150" x2="250" y2="58" stroke="#111" stroke-width="2"/>'+T(262,62,'ŷ',14,'start')
    pts=[('y1',90,100,'above'),('y2',130,95,'above'),('y3',100,175,'below'),('y4',180,40,'above'),('y5',145,170,'below'),('y6',195,160,'below')]
    for n,x,y,pos in pts:
        o+=f'<circle cx="{x}" cy="{y}" r="3.5" fill="#111"/>'+T(x-12 if pos=='above' else x+2,y-8 if pos=='above' else y+16,n[0]+'<tspan font-size="9" dy="3">'+n[1]+'</tspan>',13,'start')
    o+='<line x1="195" y1="160" x2="195" y2="95" stroke="#111" stroke-width="1.5"/>'+T(206,132,'e = y − ŷ',12,'start')
    return svg(W,H,'Six observed points y1 to y6 scattered about a fitted regression line ŷ, with the residual e = y minus ŷ shown as a vertical segment from a point to the line',o)
